<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order #{{ $order->number }}</title><link rel="stylesheet" href="{{ asset('shop.css') }}"><style>main{max-width:650px;margin:30px auto;padding:20px}.panel{padding:25px}.summary-line{display:flex;justify-content:space-between;margin:12px 0}.checkout-form label{display:block;margin:15px 0}.checkout-form input,.checkout-form select{display:block;width:100%;padding:10px;border:1px solid #bbb;border-radius:8px}.button{padding:12px 18px;cursor:pointer}.notice{color:#b91c1c}@media print{.no-print,header{display:none!important}body{background:white}.panel{border:0}}</style></head><body><header class="no-print"><a href="{{ route('dashboard') }}">← Cecilian Bites Cashier</a> | <a href="{{ route('cashier.transactions') }}">Transactions</a></header><main><section class="panel"><h2>CECILIAN BITES · Receipt #{{ $order->number }}</h2><p>{{ $order->customer_name }} · {{ $order->type->label() }} · {{ $order->created_at->format('M d, Y h:i A') }}</p>@if(session('success'))<p>{{ session('success') }}</p>@endif @if($errors->any())<div class="notice no-print">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif @foreach($order->items as $item)<div class="summary-line"><span>{{ $item->quantity }} × {{ $item->name }}</span><strong>₱{{ number_format($item->price*$item->quantity,2) }}</strong></div>@endforeach<hr><div class="summary-line"><span>Subtotal</span><strong>₱{{ number_format($order->total,2) }}</strong></div>@if($order->paid_at)<div class="summary-line"><span>Discount</span><strong>−₱{{ number_format($order->discount,2) }}</strong></div><div class="summary-line"><strong>Amount paid</strong><strong>₱{{ number_format($order->amount_paid ?? $order->total,2) }}</strong></div><p>Payment: {{ strtoupper($order->payment_method ?? 'cash') }} @if($order->payment_reference) · Ref: {{ $order->payment_reference }} @endif</p>@if(($order->payment_method ?? 'cash')==='cash')<p>Cash received: ₱{{ number_format($order->cash_received,2) }} · Change: ₱{{ number_format(max(0,$order->cash_received-($order->amount_paid ?? $order->total)),2) }}</p>@endif<p>Paid: {{ $order->paid_at->format('M d, Y h:i A') }}</p>@if($order->refunded_at)<strong>REFUNDED {{ $order->refunded_at->format('M d, Y h:i A') }}</strong><p>{{ $order->refund_reason }}</p>@endif<button class="button no-print" onclick="window.print()">Print receipt</button>@if(auth()->user()->isAdmin() && !$order->refunded_at)<form class="no-print" method="post" action="{{ route('admin.orders.refund',$order) }}" onsubmit="return confirm('Record a full refund? You must return the money separately.')">@csrf<label>Refund reason <input required minlength="5" maxlength="500" name="reason"></label><button class="button">Record full refund (admin only)</button></form>@endif
@elseif($order->status !== \App\Enums\OrderStatus::Canceled)<form class="checkout-form no-print" method="post" action="{{ route('orders.payment.store',$order) }}">@csrf<label>Payment method<select name="payment_method" id="method"><option value="cash">Cash</option><option value="gcash">GCash</option><option value="maya">Maya</option></select></label><label>Discount (₱)<input id="discount" type="number" name="discount" min="0" max="{{ $order->total }}" step="0.01" value="0"></label><p>Amount due: <strong id="due">₱{{ number_format($order->total,2) }}</strong></p><label id="cash-box">Cash received<input id="cash" type="number" name="cash_received" step="0.01" min="0" value="{{ $order->total }}"></label><p id="change-box">Change: <strong id="change">₱0.00</strong></p><label id="reference-box" hidden>Verified GCash/Maya reference<input name="payment_reference" maxlength="100" id="reference"></label><p>Verify receipt of GCash/Maya funds in your merchant account before confirming. This form does not charge a wallet.</p><button class="button">Confirm payment</button></form><script>const method=document.getElementById('method'),discount=document.getElementById('discount'),cash=document.getElementById('cash'),ref=document.getElementById('reference');function update(){let digital=method.value!=='cash',due=Math.max(0,Math.round(({{ (float)$order->total }}-Number(discount.value||0))*100)/100);document.getElementById('cash-box').hidden=digital;document.getElementById('change-box').hidden=digital;document.getElementById('reference-box').hidden=!digital;cash.required=!digital;ref.required=digital;document.getElementById('due').textContent='₱'+due.toFixed(2);document.getElementById('change').textContent='₱'+Math.max(0,Number(cash.value||0)-due).toFixed(2)}[method,discount,cash].forEach(x=>x.addEventListener('input',update));update();</script>@else<p>Canceled order — payment unavailable.</p>@endif</section></main></body></html>
